export const LEX_STRING_SRC="\nI64 LexInStr(CCmpCtrl *cc,U8 *buf,I64 size,Bool *done)\n{//Decode one caller-owned string chunk, retaining native stream state.\n  I64 i=0,j,k,ch;\n  *done=TRUE;\n  while (i<size-1) {\n    ch=LexGetChar(cc);\n    if (!ch || ch=='\"') {\n      buf[i++]=0;\n      return i;\n    } else if (ch=='\\\\') {\n      switch (ch=LexGetChar(cc)) {\n\tcase '0':\n\t  buf[i++]=0;\n\t  break;\n\tcase '\\'':\n\t  buf[i++]='\\'';\n\t  break;\n\tcase '\\`':\n\t  buf[i++]='\\`';\n\t  break;\n\tcase '\\\\':\n\t  buf[i++]='\\\\';\n\t  break;\n\tcase '\"':\n\t  buf[i++]='\"';\n\t  break;\n\tcase 'd':\n\t  buf[i++]='$$';\n\t  break;\n\tcase 'n':\n\t  buf[i++]='\\n';\n\t  break;\n\tcase 'r':\n\t  buf[i++]='\\r';\n\t  break;\n\tcase 't':\n\t  buf[i++]='\\t';\n\t  break;\n\tcase 'x':\n\tcase 'X':\n\t  j=0;\n\t  for (k=0;k<2;k++) {\n\t    ch=ToUpper(LexGetChar(cc));\n\t    if (Bt(char_bmp_hex_numeric,ch)) {\n\t      if (ch<='9')\n\t\tj=j<<4+ch-'0';\n\t      else\n\t\tj=j<<4+ch-'A'+10;\n\t    } else {\n\t      cc->flags|=CCF_USE_LAST_U16;\n\t      break;\n\t    }\n\t  }\n\t  buf[i++]=j;\n\t  break;\n\tdefault:\n\t  cc->flags|=CCF_USE_LAST_U16;\n\t  buf[i++]='\\\\';\n      }\n    } else if (ch=='$$') {\n      buf[i++]='$$';\n      if (cc->dollar_cnt)\n\tcc->dollar_cnt--;\n      else if (LexGetChar(cc)!='$$') {\n\tcc->dollar_cnt=1;\n\tcc->flags|=CCF_USE_LAST_U16;\n      }\n    } else\n      buf[i++]=ch;\n  }\n  *done=FALSE;\n  return i;\n}\n";
export const LEX_TOKEN_DIAG_SRC="\nU0 LexHostFail(CCmpCtrl *cc,U8 *reason,I64 code='Compiler')\n{//Report host error data; native debugger and Adam diagnostics are unavailable.\n  CLexFile *tmpf=NULL;\n  U8 *filename=NULL;\n  I64 line=0,offset=-1,col=-1,token=0,last_line=0;\n  if (cc) {\n    if (code=='Compiler') cc->error_cnt++;\n    token=cc->token;\n    last_line=cc->last_line_num;\n    if (tmpf=cc->lex_include_stk) {\n      filename=tmpf->full_name;\n      line=tmpf->line_num;\n      if (!(tmpf->flags&LFSF_DOC) && cc->cur_buf_ptr) {\n\tif (tmpf->buf) offset=cc->cur_buf_ptr-tmpf->buf;\n\tif (tmpf->line_start) col=cc->cur_buf_ptr-tmpf->line_start;\n      }\n    }\n  }\n  __lex_error(Fs,code,reason,filename,line,offset,col,token,last_line);\n  throw(code);\n}\n";
export const LEX_TOKEN_SRC="\nI64 Lex(CCmpCtrl *cc)\n{//Fetch next token.\n  I64 i,j,k,l,ch;\n  CHash *tmph;\n  Bool str_done,neg_e;\n  U8 *buf2=NULL,*buf3=NULL,buf[STR_LEN];\n  if (!cc) LexHostFail(NULL,\"Missing compiler control\",'LexState');\n  if (!cc->lex_include_stk)\n    LexHostFail(cc,\"Missing source stream\",'LexState');\n  try {\n    cc->last_line_num=cc->lex_include_stk->line_num;\n    while (TRUE) {\nlex_cont:\n      switch [ch=LexGetChar(cc)] {\n\tcase 0:\n\t  return cc->token=TK_EOF;\n\tcase TK_SUPERSCRIPT:\n\t  ch='>';\n\t  goto lex_ident;\n\tcase TK_SUBSCRIPT:\n\t  ch='<';\n\t  goto lex_ident;\n\tcase TK_NORMALSCRIPT:\n\t  ch='=';\n\t  goto lex_ident;\n\tcase '@':\n\t  if (cc->flags&CCF_KEEP_AT_SIGN) {\n\t    cc->token=ch;\n\t    goto lex_end;\n\t  }\n\tcase 'A'...'Z':\n\tcase 'a'...'z':\n\tcase '_':\n\tcase 128...255:\nlex_ident:\n\t  i=0;\n\t  buf[i++]=ch;\n\t  while (TRUE) {\n\t    if (i>=STR_LEN)\n\t      LexHostFail(cc,\"Ident limited to STR_LEN chars at \");\n\t    else if (!(ch=LexGetChar(cc)))\n\t      break;\n\t    else if (Bt(cc->char_bmp_alpha_numeric,ch))\n\t      buf[i++]=ch;\n\t    else if (ch==TK_SUPERSCRIPT)\n\t      buf[i++]='>';\n\t    else if (ch==TK_SUBSCRIPT)\n\t      buf[i++]='<';\n\t    else if (ch==TK_NORMALSCRIPT)\n\t      buf[i++]='=';\n\t    else {\n\t      cc->flags|=CCF_USE_LAST_U16;\n\t      break;\n\t    }\n\t  }\n\t  buf[i++]=0;\n\t  tmph=NULL;\n\t  if (cc->htc.local_var_lst)\n\t    cc->local_var_entry=MemberFind(buf,cc->htc.local_var_lst);\n\t  else\n\t    cc->local_var_entry=NULL;\n\t  if (!cc->local_var_entry && cc->htc.hash_table_lst)\n\t    tmph=HashFind(buf,cc->htc.hash_table_lst,cc->htc.hash_mask);\n\t  if (tmph)\n\t    j=tmph->type;\n\t  else\n\t    j=0;\n\t  if (j & HTT_DEFINE_STR && !(cc->flags & CCF_NO_DEFINES)) {\n\t    buf2=StrNew(tmph(CHashDefineStr *)->data);\n\t    LexIncludeStr(cc,tmph->str,buf2,FALSE);\n\t    buf2=NULL;\n\t    cc->lex_include_stk->flags|=LFSF_DEFINE;\n\t  } else {\n\t    cc->hash_entry=tmph;\n\t    buf2=StrNew(buf);\n\t    Free(cc->cur_str);\n\t    cc->cur_str=buf2;\n\t    buf2=NULL;\n\t    cc->cur_str_len=i;\n\t    cc->token=TK_IDENT;\n\t    goto lex_end;\n\t  }\n\t  break;\n\tcase '0'...'9':\n\t  i=ch-'0';\n\t  ch=ToUpper(LexGetChar(cc));\n\t  if (ch=='X') {\n\t    while (TRUE) {\n\t      ch=ToUpper(LexGetChar(cc));\n\t      if (Bt(char_bmp_hex_numeric,ch)) {\n\t\tif (ch<='9')\n\t\t  i=i<<4+ch-'0';\n\t\telse\n\t\t  i=i<<4+ch-'A'+10;\n\t      } else {\n\t\tcc->cur_i64=i;\n\t\tcc->flags|=CCF_USE_LAST_U16;\n\t\tcc->token=TK_I64;\n\t\tgoto lex_end;\n\t      }\n\t    }\n\t  } else if (ch=='B') {\n\t    while (TRUE) {\n\t      ch=LexGetChar(cc);\n\t      if (ch=='0')\n\t\ti=i<<1;\n\t      else if (ch=='1')\n\t\ti=i<<1+1;\n\t      else {\n\t\tcc->cur_i64=i;\n\t\tcc->flags|=CCF_USE_LAST_U16;\n\t\tcc->token=TK_I64;\n\t\tgoto lex_end;\n\t      }\n\t    }\n\t  }\n\t  while (TRUE) {\n\t    if (Bt(char_bmp_dec_numeric,ch))\n\t      i=i*10+ch-'0';\n\t    else {\n\t      if (ch=='.' || ch=='e' || ch=='E') break;\nlex_is_int:\n\t      cc->cur_i64=i;\n\t      cc->flags|=CCF_USE_LAST_U16;\n\t      cc->token=TK_I64;\n\t      goto lex_end;\n\t    }\n\t    ch=LexGetChar(cc);\n\t  }\n\t  if (ch=='.') {\n\t    ch=LexGetChar(cc);\n\t    if (ch=='.') {\n\t      cc->flags|=CCF_LAST_WAS_DOT;\n\t      goto lex_is_int;\n\t    }\n\t  }\nlex_float_start:\n\t  k=0;\n\t  while (TRUE) {\n\t    if (Bt(char_bmp_dec_numeric,ch)) {\n\t      i=i*10+ch-'0';\n\t      k++;\n\t    } else {\n\t      if (ch=='e' || ch=='E')\n\t\tbreak;\n\t      cc->cur_f64=i*Pow10I64(-k);\n\t      cc->flags|=CCF_USE_LAST_U16;\n\t      cc->token=TK_F64;\n\t      goto lex_end;\n\t    }\n\t    ch=LexGetChar(cc);\n\t  }\n\t  ch=LexGetChar(cc);\n\t  neg_e=FALSE;\n\t  if (ch=='-') {\n\t    neg_e=TRUE;\n\t    ch=LexGetChar(cc);\n\t  }\n\t  j=0;\n\t  while (TRUE) {\n\t    if (Bt(char_bmp_dec_numeric,ch))\n\t      j=j*10+ch-'0';\n\t    else {\n\t      if (neg_e)\n\t\tcc->cur_f64=i*Pow10I64(-j-k);\n\t      else\n\t\tcc->cur_f64=i*Pow10I64(j-k);\n\t      cc->flags|=CCF_USE_LAST_U16;\n\t      cc->token=TK_F64;\n\t      goto lex_end;\n\t    }\n\t    ch=LexGetChar(cc);\n\t  }\n\t  break;\n\tcase '\"':\n\t  cc->flags|=CCF_IN_QUOTES;\n\t  buf2=NULL;\n\t  i=0;\n\t  do {\n\t    j=LexInStr(cc,buf,STR_LEN,&str_done);\n\t    buf3=MAlloc(i+j);\n\t    if (buf2) {\n\t      MemCpy(buf3,buf2,i);\n\t      Free(buf2);\n\t    }\n\t    buf2=buf3;\n\t    buf3=NULL;\n\t    MemCpy(buf2+i,buf,j);\n\t    i+=j;\n\t  } while (!str_done);\n\t  buf3=MAlloc(i);\n\t  MemCpy(buf3,buf2,i);\n\t  Free(buf2);\n\t  buf2=NULL;\n\t  Free(cc->cur_str);\n\t  cc->cur_str=buf3;\n\t  buf3=NULL;\n\t  cc->cur_str_len=i;\n\t  cc->flags&=~CCF_IN_QUOTES;\n\t  cc->token=TK_STR;\n\t  goto lex_end;\n\tcase '\\'':\n\t  if (cc->flags&CCF_NO_CHAR_CONST)\n\t    break;\n\t  k=0;\n\t  for (j=0;j<8;j++) {\n\t    if (!(ch=LexGetChar(cc)) || ch=='\\'')\n\t      break;\n\t    if (ch=='\\\\') {\n\t      switch (ch=LexGetChar(cc)) {\n\t\tcase '0':\t  k.u8[j]=0;\t  break;\n\t\tcase '\\'':\t  k.u8[j]='\\'';   break;\n\t\tcase 0x60:\t  k.u8[j]=0x60;   break;\n\t\tcase '\"':\t  k.u8[j]='\"';\t  break;\n\t\tcase '\\\\':\t  k.u8[j]='\\\\';   break;\n\t\tcase 'd':\t  k.u8[j]='$$';   break;\n\t\tcase 'n':\t  k.u8[j]='\\n';   break;\n\t\tcase 'r':\t  k.u8[j]='\\r';   break;\n\t\tcase 't':\t  k.u8[j]='\\t';   break;\n\t\tcase 'x':\n\t\tcase 'X':\n\t\t  i=0;\n\t\t  for (l=0;l<2;l++) {\n\t\t    ch=ToUpper(LexGetChar(cc));\n\t\t    if (Bt(char_bmp_hex_numeric,ch)) {\n\t\t      if (ch<='9')\n\t\t\ti=i<<4+ch-'0';\n\t\t      else\n\t\t\ti=i<<4+ch-'A'+10;\n\t\t    } else {\n\t\t      cc->flags|=CCF_USE_LAST_U16;\n\t\t      break;\n\t\t    }\n\t\t  }\n\t\t  k.u8[j]=i;\n\t\t  break;\n\t\tdefault:\n\t\t  k.u8[j]='\\\\';\n\t\t  cc->flags|=CCF_USE_LAST_U16;\n\t      }\n\t    } else if (ch=='$$') {\n\t      ch=LexGetChar(cc);\n\t      k.u8[j]='$$';\n\t      if (ch!='$$')\n\t\tcc->flags|=CCF_USE_LAST_U16;\n\t    } else\n\t      k.u8[j]=ch;\n\t  }\n\t  if (ch!='\\'' && (ch=LexGetChar(cc)) && ch!='\\'')\n\t    LexHostFail(cc,\"Char const limited to 8 chars at \");\n\t  cc->cur_i64=k;\n\t  cc->token=TK_CHAR_CONST;\n\t  goto lex_end;\n\tcase '#':\n\t  if (cc->flags&CCF_KEEP_SIGN_NUM) {\n\t    cc->token=ch;\n\t    goto lex_end;\n\t  }\n\t  if (Lex(cc)!=TK_IDENT)\t//skip '#'\n\t    goto lex_end;\n\t  if (!(tmph=cc->hash_entry))\n\t    goto lex_end;\n\t  if (!(tmph->type & HTT_KEYWORD))\n\t    goto lex_end;\n\t  switch (i=tmph(CHashGeneric *)->user_data0) {\n\t    case KW_INCLUDE:\n\t      if (Lex(cc)!=TK_STR)\n\t\tgoto lex_end;\n\t      buf3=ExtDft(cc->cur_str,\"HC.Z\");\n\t      buf2=FileNameAbs(buf3);\n\t      Free(buf3);\n\t      buf3=NULL;\n\t      if (Bt(&sys_run_level,RLf_DOC))\n\t\tLexAttachDoc(cc,,,buf2);\n\t      else\n\t\tLexIncludeStr(cc,buf2,FileRead(buf2),TRUE);\n\t      Free(buf2);\n\t      buf2=NULL;\n\t      break;\n//Back with the compiler's directives (A): V5.03 Lex.HC:712-1000, #define,\n//#if, #ifdef, #ifndef, #ifaot, #ifjit, #else, #endif, #assert, #exe and\n//#help_index, #help_file.\n\t    default:\n\t      LexHostFail(cc,\"Compiler directives require native execution\",\n\t\t    'LexCaps');\n\t  }\n\t  break;\n\tcase '\\n':\n\t  if (!(cc->flags&CCF_KEEP_NEW_LINES))\n\t    break; //else fall through\n\tcase TK_INS_BIN:\n\tcase TK_INS_BIN_SIZE:\n\t  cc->token=ch;\n\t  goto lex_end;\n\tcase '.':\n\t  if (cc->flags&CCF_KEEP_DOT) {\n\t    cc->token=ch;\n\t    goto lex_end;\n\t  }\n\t  if (cc->flags&CCF_LAST_WAS_DOT) {\n\t    cc->flags&=~CCF_LAST_WAS_DOT;\n\t    goto lex_dot_dot;\n\t  }\n\t  ch=LexGetChar(cc);\n\t  if ('0'<=ch<='9') {\n\t    i=0;\n\t    goto lex_float_start;\n\t  } else if (ch=='.') {\nlex_dot_dot:\n\t    cc->token=TK_DOT_DOT;\n\t    if (LexGetChar(cc)=='.')\n\t      cc->token=TK_ELLIPSIS;\n\t    else\n\t      cc->flags|=CCF_USE_LAST_U16;\n\t    goto lex_end;\n\t  }\n\t  cc->flags|=CCF_USE_LAST_U16;\n\t  cc->token='.';\n\t  goto lex_end;\n\tcase '!':\n\tcase '$$'...'&':\n\tcase '('...'-':\n\tcase '/':\n\tcase ':'...'?':\n\tcase '[':\n\tcase ']'...'^':\n\tcase '{'...'~':\n\tcase 0x60:\n\t  if (!(i=cmp.dual_U16_tokens1[ch])) {\n\t    if (ch=='$$') {\n\t      ch=LexGetChar(cc);\n\t      if (ch=='$$') {\n\t\tcc->token='$$';\n\t\tgoto lex_end;\n\t      } else if (ch) {\n\t\tdo ch=LexGetChar(cc);\n\t\twhile (ch && ch!='$$');\n\t\tif (!ch) {\n\t\t  cc->token=TK_EOF;\n\t\t  goto lex_end;\n\t\t} else\n\t\t  goto lex_cont;\n\t      } else {\n\t\tcc->flags|=CCF_USE_LAST_U16;\n\t\tcc->token='$$';\n\t\tgoto lex_end;\n\t      }\n\t    } else {\n\t      cc->token=ch;\n\t      goto lex_end;\n\t    }\n\t  } else {\n\t    j=LexGetChar(cc);\n\t    if (i.u16[0]==j) {\n\t      i>>=16;\n\t      if (!i) {//Block comment.\n\t\tj=1;\n\t\tdo {\n\t\t  if (!(ch=LexGetChar(cc)))\n\t\t    return cc->token=TK_EOF;\nlex_check_comment:\n\t\t  if (ch=='*') {\n\t\t    if (!(ch=LexGetChar(cc)))\n\t\t      return cc->token=TK_EOF;\n\t\t    if (ch=='/')\n\t\t      j--;\n\t\t    else\n\t\t      goto lex_check_comment;\n\t\t  } else if (ch=='/') {\n\t\t    if (!(ch=LexGetChar(cc)))\n\t\t      return cc->token=TK_EOF;\n\t\t    if (ch=='*')\n\t\t      j++;\n\t\t    else\n\t\t      goto lex_check_comment;\n\t\t  }\n\t\t} while (j);\n\t\tgoto lex_cont;\n\t      } else {\n\t\tcc->token=i;\n\t\tgoto lex_end;\n\t      }\n\t    }\n\t    if (i=cmp.dual_U16_tokens2[ch]) {\n\t      if (i.u16[0]==j) {\n\t\ti>>=16;\n\t\tif (!i) {//Line comment.\n\t\t  LexSkipEol(cc);\n\t\t  if (cc->flags&CCF_KEEP_NEW_LINES) {\n\t\t    cc->token='\\n';\n\t\t    goto lex_end;\n\t\t  } else\n\t\t    goto lex_cont;\n\t\t} else {\n\t\t  if (i==TK_SHL || i==TK_SHR) {\n\t\t    j=LexGetChar(cc);\n\t\t    if (j=='=') {\n\t\t      if (i==TK_SHL)\n\t\t\ti=TK_SHL_EQU;\n\t\t      else\n\t\t\ti=TK_SHR_EQU;\n\t\t    } else\n\t\t      cc->flags|=CCF_USE_LAST_U16;\n\t\t  }\n\t\t  cc->token=i;\n\t\t  goto lex_end;\n\t\t}\n\t      }\n\t      if (i=cmp.dual_U16_tokens3[ch]) {\n\t\tif (i.u16[0]==j) {\n\t\t  cc->token=i.u16[1];\n\t\t  goto lex_end;\n\t\t}\n\t      }\n\t    }\n\t    cc->flags|=CCF_USE_LAST_U16;\n\t    cc->token=ch;\n\t    goto lex_end;\n\t  }\n\tcase TK_TKS_NUM:\n\t  break;\n      }\n    }\nlex_end:\n    LexGetChar(cc); //Do this so WAS_NEW_LINE is right\n    cc->flags|=CCF_USE_LAST_U16;\n    return cc->token;\n  } catch {\n    Free(buf2);\n    Free(buf3);\n  }\n  return TK_EOF;\n}\n";
export const MEMBER_SRC="\nI64 MemberMetaData(U8 *needle_str,CMemberLst *haystack_member_lst)\n{//Find meta data name, return meta data val. See $LK,\"::/Demo/ClassMeta.HC\"$.\n  CMemberLstMeta *meta=haystack_member_lst->meta;\n  while (meta) {\n    if (!StrCmp(meta->str,needle_str))\n      return meta->user_data;\n    meta=meta->next;\n  }\n  return 0;\n}\n\nCMemberLstMeta *MemberMetaFind(U8 *needle_str,CMemberLst *haystack_member_lst)\n{//Find meta data name, return meta data struct. See $LK,\"::/Demo/ClassMeta.HC\"$.\n  CMemberLstMeta *meta=haystack_member_lst->meta;\n  while (meta) {\n    if (!StrCmp(meta->str,needle_str))\n      return meta;\n    meta=meta->next;\n  }\n  return NULL;\n}\n\nCMemberLst *MemberFind(U8 *needle_str,CHashClass *haystack_class)\n{//Find class member. See $LK,\"ClassRep\",A=\"MN:ClassRep\"$() and $LK,\"DocForm\",A=\"MN:DocForm\"$().\n  I64 i;\n  CMemberLst *tmpm;\n  do {\n    tmpm=haystack_class->member_lst_and_root;\n    while (tmpm) {\n      if (!(i=StrCmp(tmpm->str,needle_str))) {\n\ttmpm->use_cnt++;\n\treturn tmpm;\n      }\n      if (i<=0)\n\ttmpm=tmpm->left;\n      else\n\ttmpm=tmpm->right;\n    }\n  } while (haystack_class=haystack_class->base_class);\n  return NULL;\n}\n\nCMemberLst *MemberClassBaseFind(CHashClass *needle_class,\n\tCHashClass *haystack_class)\n{//Find class member class base. For finding dup class local vars.\n  CMemberLst *tmpm;\n  tmpm=haystack_class->member_class_base_root;\n  while (tmpm) {\n    if (needle_class==tmpm->member_class_base)\n      return tmpm;\n    if (needle_class<tmpm->member_class_base)\n      tmpm=tmpm->left_class_base;\n    else\n      tmpm=tmpm->right_class_base;\n  }\n  return NULL;\n}\n\nBool  MemberLstCmp(CMemberLst *tmpm1,CMemberLst *tmpm2,I64 cnt=I64_MAX)\n{\n  while (tmpm1 && tmpm2 && cnt--) {\n    if (StrCmp(tmpm1->str,tmpm2->str) ||\n\t  tmpm1->member_class!=tmpm2->member_class ||\n\t  tmpm1->member_class_base!=tmpm2->member_class_base)\n      return FALSE;\n    if (tmpm1->flags&MLF_DFT_AVAILABLE || tmpm2->flags&MLF_DFT_AVAILABLE) {\n      if (tmpm1->flags&(MLF_DFT_AVAILABLE|MLF_STR_DFT_AVAILABLE)!=\n\t    tmpm2->flags&(MLF_DFT_AVAILABLE|MLF_STR_DFT_AVAILABLE))\n\treturn FALSE;\n      if (tmpm1->flags&MLF_STR_DFT_AVAILABLE) {\n\tif (StrCmp(tmpm1->dft_val,tmpm2->dft_val))\n\t  return FALSE;\n      } else if (tmpm1->dft_val!=tmpm2->dft_val)\n\treturn FALSE;\n    }\n    tmpm1=tmpm1->next;\n    tmpm2=tmpm2->next;\n  }\n  if (cnt<0 || !tmpm1 && !tmpm2)\n    return TRUE;\n  else\n    return FALSE;\n}\n\n//V5.03 Compiler/OptLib.HC OptClassFwd.\nCHashClass *OptClassFwd(CHashClass *tmpc)\n{//Class forwarding for unions and subclasses.\n  CHashClass *tmpc1;\n  while (tmpc1=tmpc->fwd_class)\n    tmpc=tmpc1;\n  return tmpc;\n}\n\nI64 MemberLstSize(CHashClass *tmpc)\n{\n  CMemberLst *tmpm;\n  CMemberLstMeta *tmp_meta;\n  I64 res=0;\n  tmpm=tmpc->member_lst_and_root;\n  while (tmpm) {\n    res+=MSize2(tmpm->str);\n    res+=LinkedLstSize(tmpm->dim.next);\n    if (tmpm->flags & MLF_STR_DFT_AVAILABLE)\n      res+=MSize2(tmpm->dft_val);\n    if (tmpm->flags & MLF_FUN)\n      res+=HashEntrySize2(tmpm->fun_ptr-tmpm->fun_ptr->ptr_stars_cnt);\n    tmp_meta=tmpm->meta;\n    while (tmp_meta) {\n      res+=MSize2(tmp_meta->str);\n      if (tmp_meta->flags&MLMF_IS_STR)\n\tres+=MSize2(tmp_meta->user_data);\n      res+=MSize2(tmp_meta);\n      tmp_meta=tmp_meta->next;\n    }\n    res+=MSize2(tmpm);\n    tmpm=tmpm->next;\n  }\n  return res;\n}\n";
export const CHASH_SRC="//V5.03 Compiler/CHash.HC: HashEntrySize2 and HashTableSize2.\n\nI64 HashEntrySize2(CHashSrcSym *tmph)\n{//Memory size of a std system hash entry.\n  CDbgInfo *dbg_info;\n  I64 res=MSize2(tmph);\n  if (!(tmph->type&HTT_DICT_WORD))\n    res+=MSize2(tmph->str);\n  if (tmph->type & HTG_SRC_SYM) {\n    res+=MSize2(tmph->src_link);\n    res+=MSize2(tmph->idx);\n    res+=MSize2(tmph->import_name);\n    res+=LinkedLstSize(tmph->ie_lst);\n    if (tmph->type & (HTT_FUN | HTT_EXPORT_SYS_SYM))\n      res+=MSize2(tmph->dbg_info);\n    if (tmph->type & HTT_CLASS)\n      res+=MemberLstSize(tmph);\n    else if (tmph->type & HTT_FUN) {\n      res+=MemberLstSize(tmph);\n      if (dbg_info=tmph->dbg_info)\n//This should be $LK,\"MSize\",A=\"MN:MSize\"$() but it would crash on AOT .BIN.Z file funs.\n\tres+=dbg_info->body[dbg_info->max_line+1-dbg_info->min_line]\n\t      -dbg_info->body[0];\n    } else if (tmph->type&HTT_DEFINE_STR)\n      res+=MSize2(tmph(CHashDefineStr *)->data);\n    else if (tmph->type & HTT_GLBL_VAR) {\n      res+=LinkedLstSize(tmph(CHashGlblVar *)->dim.next);\n      if (!(tmph(CHashGlblVar *)->flags&GVF_ALIAS))\n\tres+=MSize2(tmph(CHashGlblVar *)->data_addr);\n      if (tmph(CHashGlblVar *)->fun_ptr)\n\tres+=HashEntrySize2(tmph(CHashGlblVar *)->fun_ptr\n\t      -tmph(CHashGlblVar *)->fun_ptr->ptr_stars_cnt);\n    }\n  } else if (tmph->type & HTT_FILE)\n    res+=MSize2(tmph(CHashGeneric *)->user_data0);\n  else if (tmph->type & HTT_MODULE &&\n\tStrCmp(tmph->str,KERNEL_MODULE_NAME))\n    res+=MSize2(tmph(CHashGeneric *)->user_data0);\n  return res;\n}\n\nI64 HashTableSize2(CHashTable *table)\n{//Memory size of std system hash table and all entries.\n  I64 i,res=0;\n  CHashSrcSym *tmph;\n  if (!table)\n    return 0;\n  for (i=0;i<=table->mask;i++) {\n    tmph=table->body[i];\n    while (tmph) {\n      res+=HashEntrySize2(tmph);\n      tmph=tmph->next;\n    }\n  }\n  res+=MSize2(table->body);\n  res+=MSize2(table);\n  return res;\n}\n";
export const MENU_SRC="#help_index \"Menus\"\n#help_file \"::/Doc/Menus\"\n\nCTask *MenuTask()\n{\n  CTask *res=sys_focus_task;\n  while (res && !res->cur_menu)\n    res=res->parent_task;\n  return res;\n}\n\nCMenuEntry *sys_cur_submenu_entry=NULL;\n\npublic CMenuEntry *MenuSubEntryFind(\n\tCMenuEntry *haystack_first,U8 *needle_entry_name)\n{//You probably don't need this. Use dir / and $LK,\"MenuEntryFind\",A=\"MN:MenuEntryFind\"$().\n  while (haystack_first) {\n    if (!StrCmp(haystack_first->name,needle_entry_name))\n      return haystack_first;\n    haystack_first=haystack_first->next;\n  }\n  return NULL;\n}\n\npublic CMenuEntry *MenuEntryFind(CMenu *haystack_menu,U8 *needle_full_name)\n{//Find pulldown entry. Fs->cur_menu is probably the menu you want.\n//Just 2 levels -- across top and down are valid, currently.\n  U8 *st,*st2;\n  CMenuEntry *tmpse;\n  if (!haystack_menu || !needle_full_name)\n    return NULL;\n  st=StrNew(needle_full_name);\n  st2=StrNew(needle_full_name);\n  tmpse=(&haystack_menu->sub)(U8 *)-offset(CMenuEntry.sub);\n  while (*st && tmpse) {\n    StrFirstRem(st,\"/\",st2);\n    tmpse=MenuSubEntryFind(tmpse->sub,st2);\n  }\n  Free(st);\n  Free(st2);\n  return tmpse;\n}\n\nCMenuEntry *MenuNewSub(CCmpCtrl *cc,CTask *task)\n{\n  CMenuEntry *tmpme=NULL,*tmpse;\n  if (cc->token==TK_IDENT) {\n    tmpme=CAlloc(sizeof(CMenuEntry),task);\n    if (StrLen(cc->cur_str)>31)\n      cc->cur_str[31]=0;\n    StrCpy(tmpme->name,cc->cur_str);\n    if (Lex(cc)=='(') {\n      tmpme->msg_code=MSG_KEY_DOWN_UP;\n      if (Lex(cc)!=',' && cc->token!=')')\n\ttmpme->msg_code=LexExpressionI64(cc);\n      if (cc->token==',')\n\tLex(cc);\n      if (cc->token!=',' && cc->token!=')')\n\ttmpme->arg1=LexExpressionI64(cc);\n      if (cc->token==',')\n\tLex(cc);\n      if (cc->token!=',' && cc->token!=')')\n\ttmpme->arg2=LexExpressionI64(cc);\n      if (cc->token!=')')\n\tLexExcept(cc,\"Missing ')' at \");\n      if (Lex(cc)!=';')\n\tLexExcept(cc,\"Missing ';' at\");\n      Lex(cc); //Skip ;\n    } else if (cc->token=='{') {\n      Lex(cc); //Skip {\n      tmpme->dir=TRUE;\n      tmpse=&tmpme->sub;\n      while (tmpse && cc->token!='}')\n\ttmpse=tmpse->next=MenuNewSub(cc,task);\n      if (cc->token!='}')\n\tLexExcept(cc,\"Missing '}' at \");\n      else\n\tLex(cc); //Skip }\n    } else\n      LexExcept(cc,\"Expecting '{' at \");\n  }\n  return tmpme;\n}\n\npublic CMenu *MenuNew(U8 *st,I64 flags=0,CTask *task=NULL)\n{//Parse a menu. You probably don't need this.\n  CMenu *m;\n  CMenuEntry *tmpse;\n  CCmpCtrl *cc=CmpCtrlNew(st,CCF_DONT_FREE_BUF);\n  if (!task) task=Fs;\n  Lex(cc);\n  m=CAlloc(sizeof(CMenu),task);\n  m->task=task;\n  m->flags=flags;\n  m->attr =BLUE<<4+YELLOW;\n  tmpse=&m->sub;\n  while (tmpse)\n    tmpse=tmpse->next=MenuNewSub(cc,task);\n  CmpCtrlDel(cc);\n  return m;\n}\n\npublic CMenu *MenuFile(U8 *filename,I64 flags=0,CTask *task=NULL)\n{//Parse a pulldown menu file. You probably don't need this.\n  CMenu *m;\n  U8 *st=MStrPrint(\"#include \\\"%s\\\"\",filename);\n  m=MenuNew(st,flags,task);\n  Free(st);\n  return m;\n}\n\nU0 MenuDelSub(CMenuEntry *tmpme)\n{\n  CMenuEntry *tmpse,*tmpse1;\n  if (tmpme) {\n    tmpse=tmpme->sub;\n    while (tmpse) {\n      tmpse1=tmpse->next;\n      MenuDelSub(tmpse);\n      tmpse=tmpse1;\n    }\n    Free(tmpme);\n  }\n}\n\npublic U0 MenuDel(CMenu *m)\n{//Delete a manu. You probably don't need this.\n  CMenuEntry *tmpme,*tmpme1;\n  if (!m) return;\n  tmpme=m->sub;\n  while (tmpme) {\n    tmpme1=tmpme->next;\n    MenuDelSub(tmpme);\n    tmpme=tmpme1;\n  }\n  Free(m);\n}\n\nI64 MenuEntryWidth(CMenuEntry *tmpme)\n{\n  I64 res=StrLen(tmpme->name);\n  CMenuEntry *tmpse=tmpme->sub;\n  while (tmpse) {\n    res=MaxI64(res,StrLen(tmpse->name));\n    tmpse=tmpse->next;\n  }\n  return res+1;\n}\n\npublic CMenu *MenuPush(U8 *st)\n{//Save old pulldown menu and replace with new from str.\n  CMenu *m=MenuNew(st);\n  m->next=Fs->cur_menu;\n  Fs->cur_menu=m;\n  return m;\n}\n\npublic CMenu *MenuFilePush(U8 *filename)\n{//Save old pulldown menu and replace with new from file.\n  CMenu *m=MenuFile(filename);\n  m->next=Fs->cur_menu;\n  Fs->cur_menu=m;\n  return m;\n}\n\npublic U0 MenuPop()\n{//Restore old pulldown menu. Delete just-deactivated menu.\n  CMenu *m=Fs->cur_menu;\n  if (!m) return;\n  Fs->cur_menu=m->next;\n  MenuDel(m);\n}\n\nU0 DrawMenu(CDC *dc)\n{\n  CMenu *m;\n  CMenuEntry *tmpme,*tmpse,*cur_submenu=NULL;\n  U8 *st=NULL;\n  CTask *task=MenuTask;\n  I64 i,w,x0,y0,x1=ms.pos.x,y1=ms.pos.y;\n  if (!TaskValidate(task) || !(m=task->cur_menu)) {\n    sys_cur_submenu_entry=NULL;\n    return;\n  }\n  dc->color=m->attr>>4;\n  GrRect(dc,0,0,GR_WIDTH,FONT_HEIGHT);\n  x0=0;\n  tmpme=m->sub;\n  while (tmpme) {\n    w=MenuEntryWidth(tmpme)*FONT_WIDTH;\n    if (x0<=x1<x0+w) {\n      if (0<=y1<FONT_HEIGHT) {\n\tdc->color=m->attr&15;\n\tGrRect(dc,x0,0,w,FONT_HEIGHT);\n\tdc->color=m->attr>>4;\n      } else\n\tdc->color=m->attr&15;\n      GrPrint(dc,x0,0,\"%s\",tmpme->name);\n      y0=FONT_HEIGHT;\n      tmpse=tmpme->sub;\n      while (tmpse) {\n\tif (tmpse->checked)\n\t  i=m->attr^0xFF;\n\telse\n\t  i=m->attr;\n\tif (y0<=y1<y0+FONT_HEIGHT) {\n\t  if (tmpse->msg_code==MSG_KEY_DOWN||\n\t\ttmpse->msg_code==MSG_KEY_DOWN_UP) {\n\t    if (!tmpse->arg2)\n\t      tmpse->arg2=Char2ScanCode(tmpse->arg1);\n\t    st=ScanCode2KeyName(tmpse->arg2);\n\t  }\n\t  sys_cur_submenu_entry=cur_submenu=tmpse;\n\t  dc->color=i&15;\n\t  GrRect(dc,x0,y0,w,FONT_HEIGHT);\n\t  dc->color=i>>4;\n\t  GrPrint(dc,x0,y0,\"%s\",tmpse->name);\n\t  if (st) {\n\t    dc->color=i>>4;\n\t    GrRect(dc,x0+w,y0-FONT_HEIGHT,\n\t\t  (StrLen(st)+1)*FONT_WIDTH,FONT_HEIGHT*3);\n\t    dc->color=i&15;\n\t    GrPrint(dc,x0+w,y0,\"%s\",st);\n\t    Free(st);\n\t  }\n\t} else {\n\t  dc->color=i>>4;\n\t  GrRect(dc,x0,y0,w,FONT_HEIGHT);\n\t  dc->color=i&15;\n\t  GrPrint(dc,x0,y0,\"%s\",tmpse->name);\n\t}\n\ty0+=FONT_HEIGHT;\n\ttmpse=tmpse->next;\n      }\n    } else {\n      dc->color=m->attr&15;\n      GrPrint(dc,x0,0,\"%s\",tmpme->name);\n    }\n    x0+=w;\n    tmpme=tmpme->next;\n  }\n  sys_cur_submenu_entry=cur_submenu;\n}\n";
export const PRS_EXP_SRC="//V5.03 Compiler/PrsExp.HC compiles an expression to machine code and\n//calls it. The browser's compiler is in the host, so Lex hands it the\n//expression's tokens and the code stays there: the bin holds its handle.\n\nU8 *LexExpression2Bin(CCmpCtrl *cc,I64 *_type=NULL)\n{//Compile cc expression. You call the code.\n  I64 depth=0,*res;\n  while (TRUE) {\n    switch (cc->token) {\n      case TK_EOF:\n\tgoto le_done;\n      case '(':\n      case '[':\n\tdepth++;\n\tbreak;\n      case ')':\n      case ']':\n\tif (!depth) goto le_done;\n\tdepth--;\n\tbreak;\n      case ',':\n      case ';':\n      case ':':\n      case '{':\n      case '}':\n\tif (!depth) goto le_done;\n\tbreak;\n    }\n    __jit_tok(cc->token,cc->cur_i64,cc->cur_f64,cc->cur_str,cc->cur_str_len);\n    Lex(cc);\n  }\nle_done:\n  res=MAlloc(sizeof(I64));\n  if (!(*res=__jit_expr(_type))) {\n    Free(res);\n    LexExcept(cc,\"Invalid expression at \");\n  }\n  return res;\n}\n\nI64 LexExpressionCall(U8 *machine_code)\n{//Run $LK,\"LexExpression2Bin\",A=\"MN:LexExpression2Bin\"$ code, as Call.\n  return __jit_call(*machine_code(I64 *));\n}\n\nU0 LexExpressionFree(U8 *machine_code)\n{//Free $LK,\"LexExpression2Bin\",A=\"MN:LexExpression2Bin\"$ code.\n  if (machine_code) {\n    __jit_del(*machine_code(I64 *));\n    Free(machine_code);\n  }\n}\n\nBool IsLexExpression2Bin(CCmpCtrl *cc,U8 **_machine_code)\n{//Compile cc expression to bin. Return err status.\n  return ToBool(*_machine_code=LexExpression2Bin(cc));\n}\n\nI64 LexExpressionI64(CCmpCtrl *cc)\n{//Compile cc expression, forcing to I64 and eval.\n  U8 *machine_code;\n  I64 res,type;\n  if (machine_code=LexExpression2Bin(cc,&type)) {\n    res=LexExpressionCall(machine_code);\n    LexExpressionFree(machine_code);\n    if (type==RT_F64)\n      res=ToI64(res(F64));\n  } else\n    res=0;\n  return res;\n}\n\nF64 LexExpressionF64(CCmpCtrl *cc)\n{//Compile cc expression, forcing to F64 and eval.\n  U8 *machine_code;\n  I64 res,type;\n  if (machine_code=LexExpression2Bin(cc,&type)) {\n    res=LexExpressionCall(machine_code);\n    LexExpressionFree(machine_code);\n    if (type!=RT_F64)\n      res(F64)=ToF64(res);\n  } else\n    res=0;\n  return res(F64);\n}\n\nI64 LexExpression(CCmpCtrl *cc)\n{//Compile cc expression and eval.  Might be I64 or F64.\n  U8 *machine_code;\n  I64 res;\n  if (machine_code=LexExpression2Bin(cc)) {\n    res=LexExpressionCall(machine_code);\n    LexExpressionFree(machine_code);\n  } else\n    res=0;\n  return res;\n}\n";
export const CMAIN_SRC="//V5.03 Compiler/CMain.HC compiles text a statement at a time and runs\n//each one (ExeCmdLine). The browser's compiler is in the host: it compiles\n//the text against the program's symbols and runs it on this task.\n\nI64 ExePutS(U8 *buf,U8 *filename=NULL,\n\tI64 ccf_flags=0,CLexHashTableContext *htc=NULL)\n{//JIT Compile and execute text from a puts(\"\").\n  I64 res=0;\n  no_warn ccf_flags,htc;\n  if (!filename)\n    filename=blkdev.tmp_filename;\n  try {\n    if (!__jit_exe(buf,filename,&res))\n      throw('Compiler');\n  } catch {\n    if (Fs->except_ch=='Compiler' || Fs->except_ch=='Break') {\n      Fs->catch_except=TRUE;\n      res=0;\n    }\n  }\n  return res;\n}\n\nI64 ExePrint(U8 *fmt,...)\n{//JIT Compile and execute text from a printf().\n  I64 res;\n  U8 *buf=StrPrintJoin(NULL,fmt,argc,argv);\n  res=ExePutS(buf);\n  Free(buf);\n  return res;\n}\n\nI64 ExeFile(U8 *name,I64 ccf_flags=0)\n{//JIT Compile and execute a file.\n  I64 res;\n  U8 *name2=ExtDft(name,\"HC.Z\"),\n\t*st=MStrPrint(\"#include \\\"%s\\\";\",name2);\n  res=ExePutS(st,name,ccf_flags);\n  Free(st);\n  Free(name2);\n  return res;\n}\n\nI64 ExePutS2(U8 *buf,U8 *filename=NULL,I64 ccf_flags=0)\n{//throws exceptions\n  I64 res=0;\n  no_warn ccf_flags;\n  if (!filename)\n    filename=blkdev.tmp_filename;\n  if (!__jit_exe(buf,filename,&res))\n    throw('Compiler');\n  return res;\n}\n\nI64 ExePrint2(U8 *fmt,...)\n{//throws exceptions\n  I64 res;\n  U8 *buf=StrPrintJoin(NULL,fmt,argc,argv);\n  res=ExePutS2(buf);\n  Free(buf);\n  return res;\n}\n\nI64 ExeFile2(U8 *name,I64 ccf_flags=0)\n{//throws exceptions\n  I64 res;\n  U8 *name2=ExtDft(name,\"HC.Z\"),*st=MStrPrint(\"#include \\\"%s\\\";\",name2);\n  res=ExePutS2(st,name,ccf_flags);\n  Free(st);\n  Free(name2);\n  return res;\n}\n\nCHashGlblVar *GlblVarHashAdd(U8 *st,U8 *data_addr,I64 size,I64 cnt,\n\tBool is_array)\n{//V5.03 PrsGlblVarLst's HashAdd of a glbl the host compiled at data_addr.\n  CHashGlblVar *tmpg=CAlloc(sizeof(CHashGlblVar),Fs->code_heap);\n  tmpg->data_addr=data_addr;\n  tmpg->type=HTT_GLBL_VAR;\n  tmpg->str=StrNew(st,Fs->code_heap);\n  tmpg->size=size;\n  tmpg->dim.total_cnt=cnt;\n  if (is_array)\n    tmpg->flags|=GVF_ARRAY;\n  HashAdd(tmpg,Fs->hash_table);\n  return tmpg;\n}\n\n//V5.03 Compiler/PrsLib.HC PrsKeyWord.\nI64 PrsKeyWord(CCmpCtrl *cc)\n{//Cvt cur token to $LK,\"KEYWORD\",A=\"FF:::/Compiler/OpCodes.DD,KEYWORD\"$ or -1.\n  CHashGeneric *tmph;\n  if (cc->token==TK_IDENT &&(tmph=cc->hash_entry) && tmph->type&HTT_KEYWORD)\n    return tmph->user_data0;\n  else\n    return -1;\n}\n\n//V5.03 LexStmt2Bin has PrsStmt parse a stmt and compiles its code. Here Lex\n//reads the stmt's tokens as PrsStmt does, to one token beyond its end, and the\n//host compiles them (src/jit.js statement). The bin is the code's function\n//table entry, which $LK,\"Call\",A=\"MN:Call\"$ calls; a stmt that only declares has\n//no code (INVALID_PTR) and has run once it compiled.\nU8 *LexStmt2Bin(CCmpCtrl *cc,I64 *_type,I64 cmp_flags=CMPF_PRS_SEMICOLON)\n{//Compile one cc stmt to bin code.\n  I64 depth=0,cnt=0,kw=-1,end=0;\n  Bool to_semicolon;\n  U8 *res;\n  if (_type) *_type=RT_I64;\n  while (cc->token==',')\n    Lex(cc);\n  if (cc->token==';') {\n    if (cmp_flags&CMPF_PRS_SEMICOLON)\n      Lex(cc);\n    return INVALID_PTR;\n  }\n  to_semicolon=PrsKeyWord(cc)==KW_DO;\n  try {\n    while (cc->token!=TK_EOF) {\n      if (cc->token=='}' && !depth)\n\tbreak; //The end of an $LK,\"ExeCmdLine\",A=\"MN:ExeCmdLine\"$ block.\n      switch (cc->token) {\n\tcase '(':\n\tcase '[':\n\tcase '{':\n\t  depth++;\n\t  break;\n\tcase ')':\n\tcase ']':\n\t  depth--;\n\t  break;\n\tcase '}':\n\t  if (!--depth && !to_semicolon) end='}';\n\t  break;\n\tcase ';':\n\t  if (!depth) end=';';\n\t  break;\n\tcase TK_IDENT:\n\t  kw=PrsKeyWord(cc);\n\t  if (!depth && (kw==KW_CLASS || kw==KW_UNION))\n\t    to_semicolon=TRUE;\n\t  break;\n      }\n      __jit_tok(cc->token,cc->cur_i64,cc->cur_f64,cc->cur_str,cc->cur_str_len);\n      cnt++;\n      Lex(cc);\n      if (end) {\n\tkw=PrsKeyWord(cc);\n\tif (cc->token!=',' && kw!=KW_ELSE && kw!=KW_CATCH &&\n\t      (end!='}' || cc->token!=';'))\n\t  break;\n\tend=0;\n      }\n    }\n  } catch\n    __jit_del(0); //Drop the stmt's tokens.\n  if (!cnt)\n    return INVALID_PTR;\n  if (!(res=__jit_stmt(_type)))\n    LexExcept(cc,\"Invalid statement at \");\n  return res;\n}\n\n//V5.03 Kernel/KTask.HC ExeCmdLine.\nI64 ExeCmdLine(CCmpCtrl *cc)\n{//Terminal JIT-compile-and-execute loop for CCmpCtrl.\n  I64 res=0,type,old_title_src=Fs->title_src;\n  U8 *ptr,*ptr2,*ptr3,*machine_code,*old_task_title=StrNew(Fs->task_title);\n  F64 t0;\n  CDocEntry *doc_e;\n  CDoc *doc;\n  if (Fs->title_src!=TTS_LOCKED_CONST)\n    Fs->title_src=TTS_CUR_LEX;\n  while (cc->token &&\n\t(cc->token!='}' || !(cc->flags & CCF_EXE_BLK)) ) {\n    if (Fs->title_src==TTS_CUR_LEX) {\n      ptr2=&Fs->task_title;\n      ptr3=ptr2+STR_LEN-1;\n      if (cc->lex_include_stk->flags & LFSF_DOC) {\n\tdoc_e=cc->lex_include_stk->cur_entry;\n\tdoc=cc->lex_include_stk->doc;\n\twhile (doc_e!=doc && ptr2<ptr3) {\n\t  switch (doc_e->type_u8) {\n\t    case DOCT_TEXT:\n\t      ptr=doc_e->tag;\n\t      while (*ptr && ptr2<ptr3)\n\t\t*ptr2++=*ptr++;\n\t      break;\n\t    case DOCT_TAB:\n\t    case DOCT_NEW_LINE:\n\t      *ptr2++='.';\n\t      break;\n\t  }\n\t  doc_e=doc_e->next;\n\t}\n\tif (ptr2<ptr3) *ptr2=0;\n      } else\n\tif ((ptr=cc->lex_include_stk->line_start) && *ptr)\n\t  MemCpy(ptr2,ptr,STR_LEN-1);\n    }\n    cc->flags&=~CCF_HAS_MISC_DATA;\n    machine_code=LexStmt2Bin(cc,&type);\n    if (machine_code!=INVALID_PTR) {\n      if (!(cc->flags&CCF_JUST_LOAD)) {\n\tt0=tS;\n\tres=Call(machine_code);\n\tFs->answer=res;\n\tFs->answer_type=type;\n\tFs->answer_time=tS-t0;\n\tFs->new_answer=TRUE;\n\tcc->pmt_line=0;\n      }\n//The bin is a function table entry, not a heap block (LexStmt2Bin).\n//      if (!(cc->flags&CCF_HAS_MISC_DATA))\n//\tFree(machine_code);\n    }\n  }\n  if (Fs->title_src!=TTS_LOCKED_CONST) {\n    Fs->title_src=old_title_src;\n    StrCpy(Fs->task_title,old_task_title);\n  }\n  Free(old_task_title);\n  if (cc->flags&CCF_JUST_LOAD) {\n    if (cc->error_cnt)\n      return FALSE;\n    else\n      return TRUE;\n  } else\n    return res;\n}\n";
export const CMISC_SRC="//V5.03 Compiler/CMisc.HC CmdLinePmt.\n\nU8 *CmdLinePmt()\n{\n  I64 i;\n  U8 *res,*st;\n  if (Fs->new_answer) {\n    if (Fs->answer_type&~1!=RT_I0) {\n      if (Fs->answer_type==RT_F64)\n\t\"%8.6fs ansf=%15.7g\\n\",Fs->answer_time,Fs->answer;\n      else\n\t\"%8.6fs ans=0x%08X=%d\\n\",Fs->answer_time,Fs->answer,Fs->answer;\n    } else {\n      \"%8.6fs\\n\",Fs->answer_time;\n      Fs->answer=0;\n    }\n    Fs->new_answer=FALSE;\n  }\n  if (st=DirCur) {\n    \"%s\",st;\n    Free(st);\n  }\n  '>';\n//Back with RawDr (KDbg.HC):\n//  if (IsDbgMode&&IsRaw)\n//    RawDr;\n\n  LBts(&Fs->task_flags,TASKf_CMD_LINE_PMT);\n  st=GetStr(,,GSF_SHIFT_ESC_EXIT);\n  LBtr(&Fs->task_flags,TASKf_CMD_LINE_PMT);\n\n  i=StrLen(st);\n  res=MAlloc(i+1+2);\n  MemCpy(res,st,i+1);\n  i--;\n  while (i>=0 && Bt(char_bmp_white_space,res[i]))\n    i--;\n  i++;\n  if (i>0 && res[i-1]==';')\n    res[i++]=';'; //The Lex goes one beyond\n  res[i++]='\\n';//#define goes to '\\n'\n  res[i]=0;\n\n  Free(st);\n  return res;\n}\n";
export const JOB_SRC="//V5.03 Kernel/Job.HC TaskExe, TaskText, JobResScan, JobResGet, TaskWait,\n//JobRunOne, JobsHndlr, Adam, InStr, InFile and In.\n\nCJob *TaskExe(CTask *srv,CTask *master,U8 *data,I64 flags)\n{//Queues a request to compile and execute src code text.\n  CJob *res;\n  if (!data || !TaskValidate(srv) || master && !TaskValidate(master) ||\n\tsrv->popup_task && !Bt(&srv->task_flags,TASKf_FILTER_INPUT))\n    return NULL;\n  res=ACAlloc(sizeof(CJob));\n  res->master_task=master;\n  res->job_code=JOBT_EXE_STR;\n  res->flags=flags;\n  res->aux_str=AStrNew(data);\n  res->ctrl=&srv->srv_ctrl;\n\n  PUSHFD\n  CLI\n  while (LBts(&srv->srv_ctrl.flags,JOBCf_LOCKED))\n    PAUSE\n  if (!TaskValidate(srv)) {\n    LBtr(&srv->srv_ctrl.flags,JOBCf_LOCKED);\n    POPFD\n    JobDel(res);\n    return NULL;\n  } else {\n    LBtr(&srv->task_flags,TASKf_IDLE);\n    TaskRstAwaitingMsg(srv);\n    QueIns(res,srv->srv_ctrl.last_waiting);\n    LBtr(&srv->srv_ctrl.flags,JOBCf_LOCKED);\n    if (Bt(&flags,JOBf_WAKE_MASTER)) {\n      Suspend(master);\n      Yield;\n    }\n  }\n  POPFD\n  return res;\n}\n\nextern U0 InputFilterTask(); //V5.03 Kernel/KernelC.HH.\n\nCJob *TaskText(CTask *srv,CTask *master,U8 *data,I64 flags)\n{//Post StdIn text to servant task. Tell who the master task is.\n  CJob *res;\n  CTask *task;\n  if (!data || !TaskValidate(srv) || master && !TaskValidate(master) ||\n\tsrv->popup_task && !Bt(&srv->task_flags,TASKf_FILTER_INPUT))\n    return NULL;\n  res=ACAlloc(sizeof(CJob));\n  res->master_task=master; //in case somebody cares\n  res->job_code=JOBT_TEXT_INPUT;\n  res->flags=flags;\n  res->aux_str=AStrNew(data);\n\n  PUSHFD\n  task=srv->last_input_filter_task;\n  if (Bt(&flags,JOBf_HIGHEST_PRIORITY) || task==srv) {\n    if (task!=srv)\n      TaskWait(srv);\n    task=Spawn(&InputFilterTask,NULL,\"Input Filter\",,srv);\n    CLI\n    task->next_input_filter_task=srv->next_input_filter_task;\n    task->last_input_filter_task=srv;\n    srv->next_input_filter_task=task;\n    task->next_input_filter_task->last_input_filter_task=task;\n  } else {\n    CLI\n    task=srv->next_input_filter_task;\n  }\n  res->ctrl=&task->srv_ctrl;\n  while (LBts(&task->srv_ctrl.flags,JOBCf_LOCKED))\n    PAUSE\n  if (!TaskValidate(task)) {\n    JobDel(res);\n    res=NULL;\n  } else {\n    LBtr(&task->task_flags,TASKf_IDLE);\n    TaskRstAwaitingMsg(task);\n    QueIns(res,task->srv_ctrl.last_waiting);\n    LBtr(&task->srv_ctrl.flags,JOBCf_LOCKED);\n  }\n  POPFD\n  return res;\n}\n\nBool JobResScan(CJob *rqst=NULL,I64 *_res=NULL)\n{//Check rqst complete, return with or without.\n  CJobCtrl *ctrl;\n  CJob *tmpc,*tmpc1;\n  if (!rqst || Bt(&rqst->flags,JOBf_DONE)) {\n    if (!rqst || rqst->master_task)\n      ctrl=&Fs->srv_ctrl;\n    else\n      ctrl=rqst->ctrl;\n    PUSHFD\n    CLI\n    while (LBts(&ctrl->flags,JOBCf_LOCKED))\n      PAUSE\n    tmpc1=&ctrl->next_done;\n    tmpc=tmpc1->next;\n    while (tmpc!=tmpc1) {\n      if (!rqst || rqst==tmpc) {\n\tQueRem(tmpc);\n\tLBtr(&ctrl->flags,JOBCf_LOCKED);\n\tPOPFD\n\tif (_res)\n\t  *_res=tmpc->res;\n\tJobDel(tmpc);\n\treturn TRUE;\n      }\n      tmpc=tmpc->next;\n    }\n    LBtr(&ctrl->flags,JOBCf_LOCKED);\n    POPFD\n  }\n  if (_res)\n    *_res=0;\n  return FALSE;\n}\n\nI64 JobResGet(CJob *rqst=NULL)\n{//See $LK,\"::/Demo/MultiCore/Lock.HC\"$\n  I64 res;\n  CJob *tmpc1;\n  if (!rqst) {\n    tmpc1=&Fs->srv_ctrl.next_done;\n    while (tmpc1==tmpc1->next) {\n      LBts(&Fs->task_flags,TASKf_IDLE);\n      Yield;\n    }\n  } else {\n    while (!Bt(&rqst->flags,JOBf_DONE)) {\n      LBts(&Fs->task_flags,TASKf_IDLE);\n      Yield;\n    }\n  }\n  LBtr(&Fs->task_flags,TASKf_IDLE);\n//Could get taken by someone else.\n  JobResScan(rqst,&res);\n  return res;\n}\n\nU0 TaskWait(CTask *task=NULL,Bool cmd_line_pmt=FALSE)\n{//Wait for idle.\n  CTask *task1;\n  CJob *tmpc1;\n  if (!task) task=Fs;\n  if (TaskValidate(task)) {\n    PUSHFD\n    CLI\n    while (TRUE) {\n      task1=task->last_input_filter_task;\n      tmpc1=&task1->srv_ctrl.next_waiting;\n      if (task1==Fs || !TaskValidate(task1) ||\n\t    tmpc1==tmpc1->next && Bt(&task1->task_flags,TASKf_IDLE) &&\n\t    (!cmd_line_pmt || Bt(&task1->task_flags,TASKf_CMD_LINE_PMT)))\n\tbreak;\n      Yield;\n    }\n    POPFD\n  }\n}\n\n#define JOB_DONE\t0\n#define JOB_CONT\t1\n#define JOB_EXIT\t2\n\nI64 JobRunOne(I64 run_flags,CJobCtrl *ctrl)\n{//Called with ctrl->flags,JOBCf_LOCKED.\n  CJob *tmpc=ctrl->next_waiting;\n  CTask   *master;\n  I64 res,flags=tmpc->flags,old_flags=GetRFlags;\n  if (Bt(&flags,JOBf_EXIT_ON_COMPLETE))\n    res=JOB_EXIT;\n  else\n    res=JOB_CONT;\n  switch (tmpc->job_code) {\n    case JOBT_SPAWN_TASK:\n      QueRem(tmpc);\n      LBts(&tmpc->flags,JOBf_DISPATCHED);\n      LBtr(&ctrl->flags,JOBCf_LOCKED);\n      if (tmpc->aux_str)\n\ttmpc->spawned_task=Spawn(tmpc->addr,tmpc->fun_arg,\n\t      tmpc->aux_str,,tmpc->aux1,tmpc->aux2,tmpc->flags);\n      else\n\ttmpc->spawned_task=Spawn(tmpc->addr,tmpc->fun_arg,\n\t      \"Unnamed\",,tmpc->aux1,tmpc->aux2,tmpc->flags);\n      break;\n    case JOBT_CALL:\n      QueRem(tmpc);\n      LBts(&tmpc->flags,JOBf_DISPATCHED);\n      LBtr(&ctrl->flags,JOBCf_LOCKED);\n      SetRFlags(run_flags);\n      LBtr(&Fs->task_flags,TASKf_IDLE);\n      try\n\t      tmpc->res=(*tmpc->addr)(tmpc->fun_arg);\n      catch\n\tFs->catch_except=TRUE;\n      SetRFlags(old_flags);\n      break;\n    case JOBT_EXE_STR:\n      QueRem(tmpc);\n      LBts(&tmpc->flags,JOBf_DISPATCHED);\n      LBtr(&ctrl->flags,JOBCf_LOCKED);\n      SetRFlags(run_flags);\n      LBtr(&Fs->task_flags,TASKf_IDLE);\n      try\n\t      tmpc->res=ExePrint(\"%s\",tmpc->aux_str);\n      catch\n\tFs->catch_except=TRUE;\n      SetRFlags(old_flags);\n      break;\n    default:\n      res=JOB_DONE;\n  }\n  if (res) {\n    if (master=tmpc->master_task) {\n      if (!Bt(&flags,JOBf_FREE_ON_COMPLETE)) {\n\tCLI\n\twhile (LBts(&master->srv_ctrl.flags,JOBCf_LOCKED))\n\t  PAUSE\n\tQueIns(tmpc,master->srv_ctrl.last_done);\n\tLBts(&tmpc->flags,JOBf_DONE);\n\tLBtr(&master->srv_ctrl.flags,JOBCf_LOCKED);\n\tSetRFlags(old_flags);\n      }\n      if (Bt(&flags,JOBf_FOCUS_MASTER) &&\n\t    !Bt(&master->win_inhibit,WIf_SELF_FOCUS))\n\tsys_focus_task=master;\n      if (Bt(&flags,JOBf_WAKE_MASTER))\n\tSuspend(master,FALSE);\n    }\n    if (Bt(&flags,JOBf_FREE_ON_COMPLETE))\n      JobDel(tmpc);\n    else if (!master) {\n      CLI\n      while (LBts(&ctrl->flags,JOBCf_LOCKED))\n\tYield;\n      QueIns(tmpc,ctrl->last_done);\n      LBts(&tmpc->flags,JOBf_DONE);\n      LBtr(&ctrl->flags,JOBCf_LOCKED);\n      SetRFlags(old_flags);\n    }\n  }\n  return res;\n}\n\nI64 JobsHndlr(I64 run_flags,CTask *task=NULL)\n{//Handle all waiting cmds and return.\n  I64 cnt=0,old_flags=GetRFlags;\n  if (!task) task=Fs;\n  while (TRUE) {\n    CLI\n    while (LBts(&task->srv_ctrl.flags,JOBCf_LOCKED))\n      PAUSE\n    if (task->srv_ctrl.next_waiting!=&task->srv_ctrl)\n      switch (JobRunOne(run_flags,&task->srv_ctrl)) {\n\tcase JOB_CONT:\n\t  cnt++;\n\t  break;\n\tcase JOB_EXIT:\n\t  Exit;\n\tcase JOB_DONE:\n\t  goto jh_done;\n      }\n    else\n      goto jh_done;\n  }\njh_done:\n  LBtr(&task->srv_ctrl.flags,JOBCf_LOCKED);\n  SetRFlags(old_flags);\n  return cnt;\n}\n\nI64 Adam(U8 *fmt,...)\n{//Make adam_task execute code.\n  I64 res;\n  U8 *buf=StrPrintJoin(NULL,fmt,argc,argv);\n  CJob *tmpc;\n  if (Fs==adam_task) {\n    tmpc=TaskExe(adam_task,Fs,buf,0);\n    JobsHndlr(GetRFlags);\n  } else {\n    TaskWait(adam_task);\n    tmpc=TaskExe(adam_task,Fs,buf,1<<JOBf_WAKE_MASTER);\n  }\n  JobResScan(tmpc,&res);\n  Free(buf);\n  return res;\n}\n\n//V5.03 Kernel/Job.HC XTalk and XTalkWait.\nU0 XTalk(CTask *task,U8 *fmt,...)\n{//Sends text to other task. See $LK,\"::/Misc/OSTestSuite.HC\"$.\n  U8 *buf=StrPrintJoin(NULL,fmt,argc,argv),*st=AStrNew(buf),\n\t*st2=MStrPrint(\"\\\"%%s\\\",%d;Free(%d);\",st,st);\n  TaskText(task,NULL,st2,0);\n  Free(st2);\n  Free(buf);\n}\n\nU0 XTalkWait(CTask *task,U8 *fmt,...)\n{//Send text to other task and wait for it to idle.\n  U8 *buf=StrPrintJoin(NULL,fmt,argc,argv),*st=AStrNew(buf),\n\t*st2=MStrPrint(\"\\\"%%s\\\",%d;Free(%d);\",st,st);\n  TaskText(task,NULL,st2,0);\n  Free(st2);\n  Free(buf);\n  TaskWait(task);\n}\n\nU0 InStr(U8 *fmt,...)\n{//Send InFile code to self.\n  U8 *buf=StrPrintJoin(NULL,fmt,argc,argv);\n  if (Bt(&Fs->task_flags,TASKf_INPUT_FILTER_TASK))\n    ExePrint(\"%s\",buf);\n  else\n    TaskText(Fs,NULL,buf,1<<JOBf_HIGHEST_PRIORITY);\n  Free(buf);\n}\n\nU0 InFile(U8 *filename)\n{//Send InFile code file to self.\n  U8 *name=ExtDft(filename,\"IN.Z\");\n  InStr(\"Cd(\\\"%C:%s\\\");;#include \\\"%s\\\"\",\n\tDrv2Let(Fs->cur_dv),Fs->cur_dir,name);\n  Free(name);\n}\n\nU0 In(U8 *fmt,...)\n{//Send text to own input buffer. See $LK,\"::/Demo/AcctExample/TOS/TOSDistro.HC\"$.\n  U8 *buf=StrPrintJoin(NULL,fmt,argc,argv),*st=AStrNew(buf);\n  InStr(\"\\\"%%s\\\",%d;Free(%d);\",st,st);\n  Free(buf);\n}\n\n//V5.03 Kernel/Job.HC XTalkStr and XTalkStrWait.\nU0 XTalkStr(CTask *task,U8 *fmt,...)\n{//Send InFile code to other task.\n  U8 *buf=StrPrintJoin(NULL,fmt,argc,argv);\n  TaskText(task,NULL,buf,0);\n  Free(buf);\n}\n\nU0 XTalkStrWait(CTask *task,U8 *fmt,...)\n{//Send InFile code to other task and wait for it to idle.\n  U8 *buf=StrPrintJoin(NULL,fmt,argc,argv);\n  TaskText(task,NULL,buf,0);\n  Free(buf);\n  TaskWait(task);\n}\n\n//V5.03 Kernel/Job.HC PostMsgWait, PopUp and PopUpPrint.\nU0 PostMsgWait(CTask *task,I64 msg_code,I64 arg1,I64 arg2,I64 flags=0)\n{//Post message to a task and wait until task is idle.See $LK,\"msg_code\",A=\"MN:MSG_CMD\"$.\n  PostMsg(task,msg_code,arg1,arg2,flags);\n  TaskWait(task);\n}\n\nI64 PopUp(U8 *buf,CTask *parent=NULL,CTask **_pu_task=NULL)\n{//Execute code in $LK,\"PopUp\",A=\"MN:PopUp\"$ task.\n  I64 res;\n  CJob *tmpc;\n  CTask *task=Spawn(&SrvCmdLine,NULL,\"Servant\",,parent);\n  if (!parent) {\n    TaskExe(task,parent,buf,1<<JOBf_EXIT_ON_COMPLETE|1<<JOBf_FREE_ON_COMPLETE);\n    if (_pu_task) *_pu_task=task;\n    return 0;\n  } else {\n    Fs->popup_task=task;\n    tmpc=TaskExe(task,parent,buf,1<<JOBf_WAKE_MASTER|1<<JOBf_FOCUS_MASTER);\n    if (_pu_task) *_pu_task=task;\n    JobResScan(tmpc,&res);\n    Fs->popup_task=NULL;\n    Kill(task);\n    if (_pu_task) *_pu_task=NULL;\n    return res;\n  }\n}\n\nI64 PopUpPrint(U8 *fmt,...)\n{//Execute code in $LK,\"PopUp\",A=\"MN:PopUp\"$ task.\n  U8 *buf=StrPrintJoin(NULL,fmt,argc,argv);\n  I64 res;\n  res=PopUp(buf,Fs);\n  Free(buf);\n  return res;\n}\n";
export const MESSAGE_SRC="//V5.03 Kernel/SerialDev/Message.HC. There is no debugger, so GetKey has no\n//polled branch.\nU0 InputFilterTask()\n{\n  CJob *tmpc,*tmpc1;\n  Bool old_filter;\n  I64 old_flags=GetRFlags;\n  Fs->win_inhibit=WIG_USER_TASK_DFT;\n  LBts(&Fs->task_flags,TASKf_INPUT_FILTER_TASK);\n  old_filter=LBts(&Fs->last_input_filter_task->task_flags,TASKf_FILTER_INPUT);\n  LBEqu(&Fs->task_flags,TASKf_FILTER_INPUT,old_filter);\n  while (TRUE) {\n    CLI\n    JobsHndlr(old_flags);\n    tmpc1=&Fs->srv_ctrl.next_waiting;\n    tmpc=tmpc1->next;\n    if (tmpc==tmpc1)\n      break;\n    else {\n      if (tmpc->job_code==JOBT_TEXT_INPUT) {\n\tQueRem(tmpc);\n\tSetRFlags(old_flags);\n\ttry\n\t\tExePrint(\"%s\",tmpc->aux_str);\n\tcatch\n\t  Fs->catch_except=TRUE;\n\tJobDel(tmpc);\n      } else\n\tbreak;\n    }\n  }\n  Fs->next_input_filter_task->last_input_filter_task=Fs->last_input_filter_task;\n  Fs->last_input_filter_task->next_input_filter_task=Fs->next_input_filter_task;\n  if (!old_filter)\n    LBtr(&Fs->last_input_filter_task->task_flags,TASKf_FILTER_INPUT);\n  SetRFlags(old_flags);\n}\n\nI64 ScanMsg(I64 *_arg1=NULL,I64 *_arg2=NULL,I64 mask=~1,CTask *task=NULL)\n{/*Check for a message of type specified by a one in the mask.\nThrow-out messages not in mask.\nIf no message fit mask, return NULL immediately.\nRemove desired message, return $LK,\"msg_code\",A=\"MN:MSG_CMD\"$.\nNote: This delivers messages from parent down to pop-up.\n*/\n  I64 res,old_flags;\n  CJob *tmpc,*tmpc1;\n  if (!task) task=Fs;\n  old_flags=GetRFlags;\n  tmpc1=&task->srv_ctrl.next_waiting;\n  while (TRUE) {\n    CLI\n    if (task==Fs)\n      JobsHndlr(old_flags);\n    tmpc=tmpc1->next;\n    if (tmpc==tmpc1)\n      break;\n    else {\n      if (tmpc->job_code==JOBT_MSG) {\n\tQueRem(tmpc);\n\tSetRFlags(old_flags);\n\tres=tmpc->msg_code;\n\tif (_arg1)\n\t  *_arg1=tmpc->aux1;\n\tif (_arg2)\n\t  *_arg2=tmpc->aux2;\n\tJobDel(tmpc);\n\tif ((res!=MSG_KEY_DOWN || !(tmpc->aux2&SCF_KEY_DESC) ||\n\t      !Bt(&task->win_inhibit,WIf_SELF_KEY_DESC)) && Bt(&mask,res))\n\t  goto sm_done;\n      }\n    }\n    SetRFlags(old_flags);\n  }\n  res=MSG_NULL;\n  if (_arg1)\n    *_arg1=0;\n  if (_arg2)\n    *_arg2=0;\n  if (task->parent_task&&task->parent_task->popup_task==task) {\n    SetRFlags(old_flags);\n    return ScanMsg(_arg1,_arg2,mask,task->parent_task);\n  }\nsm_done:\n  SetRFlags(old_flags);\n  return res;\n}\n\nI64 FlushMsgs(CTask *task=NULL)\n{//Throw away all messages.  Return count.\n  I64 res=0,arg1,arg2;\n  while (ScanMsg(&arg1,&arg2,~1,task))\n    res++;\n  return res;\n}\n\nI64 GetMsg(I64 *_arg1=NULL,I64 *_arg2=NULL,I64 mask=~1,CTask *task=NULL)\n{//Wait for a message of type specified by a one in the mask.\n//Throw-out all messages not in mask.\n  //Returns $LK,\"msg_code\",A=\"MN:MSG_CMD\"$. See $LK,\"::/Demo/MsgLoop.HC\"$.\n  I64 res;\n  if (!task) task=Fs;\n  LBtr(&task->task_flags,TASKf_IDLE);\n  while (!(res=ScanMsg(_arg1,_arg2,mask,task))) {\n    LBts(&task->task_flags,TASKf_IDLE);\n    Yield;\n  }\n  LBtr(&task->task_flags,TASKf_IDLE);\n  return res;\n}\n\nI64 ScanChar()\n{//Checks for $LK,\"MSG_KEY_DOWN\",A=\"MN:MSG_KEY_DOWN\"$ and returns 0 immediately if no key.\n//Waits for $LK,\"MSG_KEY_UP\",A=\"MN:MSG_KEY_UP\"$ of non-zero $LK,\"ASCII\",A=\"MN:CH_CTRLA\"$ key and returns $LK,\"ASCII\",A=\"MN:CH_CTRLA\"$ if key.\n  //$LK,\"ScanMsg\",A=\"MN:ScanMsg\"$() throws away other message types.\n  I64 arg1a,arg2a,arg1b,arg2b;\n  if (!ScanMsg(&arg1a,&arg2a,1<<MSG_KEY_DOWN)||!arg1a)\n    return 0;\n  else\n    do GetMsg(&arg1b,&arg2b,1<<MSG_KEY_UP);\n    while (!arg1b);  //Be careful of $LK,\"SC_SHIFT\",A=\"MN:SC_SHIFT\"$ and $LK,\"SC_CTRL\",A=\"MN:SC_CTRL\"$, etc.\n  return arg1a;\n}\n\nBool ScanKey(I64 *_ch=NULL,I64 *_scan_code=NULL,Bool echo=FALSE)\n{//Checks for $LK,\"MSG_KEY_DOWN\",A=\"MN:MSG_KEY_DOWN\"$ and returns FALSE immediately if no key.\n//Sets $LK,\"ASCII\",A=\"MN:CH_CTRLA\"$ and $LK,\"scan_code\",A=\"FI:::/Doc/CharOverview.DD\"$.\n  //Removes key message and returns TRUE.\n  //$LK,\"ScanMsg\",A=\"MN:ScanMsg\"$() throws away other message types.\n  I64 ch=0,sc=0;\n  if (ScanMsg(&ch,&sc,1<<MSG_KEY_DOWN)) {\n    if (_ch) *_ch=ch;\n    if (_scan_code) *_scan_code=sc;\n    if (echo)\n      PutKey(ch,sc);\n    return TRUE;\n  } else {\n    if (_ch) *_ch=0;\n    if (_scan_code) *_scan_code=0;\n    return FALSE;\n  }\n}\n\nI64 GetKey(I64 *_scan_code=NULL,Bool echo=FALSE,Bool raw_cursor=FALSE)\n{//Waits for $LK,\"MSG_KEY_DOWN\",A=\"MN:MSG_KEY_DOWN\"$ message and returns $LK,\"ASCII\",A=\"MN:CH_CTRLA\"$.\n//Sets $LK,\"scan_code\",A=\"FI:::/Doc/CharOverview.DD\"$.\n  //$LK,\"ScanKey\",A=\"MN:ScanKey\"$() throws away other message types.\n  I64 ch,sc;\n  Bool cursor_on=FALSE;\n  while (!ScanKey(&ch,&sc,FALSE)) {\n    if (IsRaw && raw_cursor) {\n      if (!cursor_on && ToI64(GetTSC*5/cnts.time_stamp_freq)&1) {\n\t'█';\n\tcursor_on=TRUE;\n      } else if (cursor_on && !(ToI64(GetTSC*5/cnts.time_stamp_freq)&1)) {\n\t'' CH_BACKSPACE;\n\tcursor_on=FALSE;\n      }\n    }\n    LBts(&Fs->task_flags,TASKf_IDLE);\n    LBts(&Fs->task_flags,TASKf_AWAITING_MSG);\n    Yield;\n    LBtr(&Fs->task_flags,TASKf_IDLE);\n  }\n  if (IsRaw && raw_cursor && cursor_on)\n    '' CH_BACKSPACE;\n  if (echo)\n    PutKey(ch,sc);\n  if (_scan_code) *_scan_code=sc;\n  return ch;\n}\n\nI64 GetChar(I64 *_scan_code=NULL,Bool echo=TRUE,Bool raw_cursor=FALSE)\n{//Waits for non-zero $LK,\"ASCII\",A=\"MN:CH_CTRLA\"$ key.\n//Sets $LK,\"scan_code\",A=\"FI:::/Doc/CharOverview.DD\"$.\n  I64 ch1;\n  do ch1=GetKey(_scan_code,FALSE,raw_cursor);\n  while (!ch1);\n  if (echo)\n    \"$$PT$$%c$$FG$$\",ch1;\n  return ch1;\n}\n\nU8 *GetStr(U8 *msg=NULL,U8 *dft=NULL,I64 flags=0)\n{//Returns a $LK,\"MAlloc\",A=\"MN:MAlloc\"$()ed prompted string.  See $LK,\"Flags\",A=\"MN:GSF_SHIFT_ESC_EXIT\"$.\n  U8 *st;\n  if (msg)\n    \"\" msg,dft;\n  st=(*fp_getstr2)(flags);\n  if (!*st) {\n    Free(st);\n    if (dft)\n      return StrNew(dft);\n    else\n      return StrNew(\"\");\n  }\n  return st;\n}\n\nI64 GetS(U8 *buf,I64 size,Bool allow_ext=TRUE)\n{//Prompt into fixed length string. Size must include terminator.\n  U8 *st;\n  I64 ch,i=0;\n  if (!size || !buf) return 0;\n  if (allow_ext) {\n    st=GetStr;\n    if (StrLen(st)>size-1) {\n      MemCpy(buf,st,size-1);\n      buf[size-1]=0;\n    } else\n      StrCpy(buf,st);\n    i=StrLen(buf);\n    Free(st);\n  } else {\n    while (TRUE) {\n      ch=GetChar(,FALSE,IsDbgMode);\n      if (ch=='\\n') {\n\t'' ch;\n\tbreak;\n      } else if (ch==CH_BACKSPACE) {\n\tif (i>0) {\n\t  i--;\n\t  '' ch;\n\t}\n      } else {\n\tif (i<size-1) {\n\t  buf[i++]=ch;\n\t  '' ch;\n\t}\n      }\n    }\n    buf[i]=0;\n  }\n  return i;\n}\n";
export const KDBG_SRC="//V5.03 Kernel/KDbg.HC's SysGetStr2, the GetStr of a task with no DolDoc\n//editor. There is no debugger.\nU8 *SysGetStr2(I64)\n{\n  U8 buf[512];\n  GetS(buf,512,FALSE);\n  return StrNew(buf);\n}\n\nU0 GetStrHostInit()\n{//fp_getstr2 as KMain sets it. DolDoc's DocGetStr2 waits on its editor.\n  fp_getstr2=&SysGetStr2;\n}\n\nI64 UnusedStk(CTask *task=NULL)\n{//Count of usused bytes in task's stk.\n  I64 res;\n  if (!task) task=Fs;\n  PUSHFD\n  CLI\n  if (task==Fs)\n    res=GetRSP()(U8 *)-(&task->stk->stk_base)(U8 *);\n  else\n    res=task->rsp(U8 *)-(&task->stk->stk_base)(U8 *);\n  POPFD\n  return res;\n}\n";
export const SND_MATH_SRC="#help_index \"Snd\"\n//CSndWaveCtrl is V5.03 Adam/Snd/MakeSnd.HC's; the rest is Adam/Snd/SndMath.HC.\nclass CSndWaveCtrl\n{\n  I64 sample_rate,sample_bits,channels;\n  F64 freq_multiplier,amp_multiplier;\n  F64 phase,last_y,last_dydt,next_y;\n};\n\n#help_index \"Snd/Math;Math\"\npublic F64 Saw(F64 t,F64 period)\n{//Sawtooth. 0.0 - 1.0 think \"(Sin+1)/2\"\n  if (period) {\n    if (t>=0.0)\n      return t%period/period;\n    else\n      return 1.0+t%period/period;\n  } else\n    return 0.0;\n}\n\npublic F64 FullSaw(F64 t,F64 period)\n{//Plus&Minus Sawtooth. 1.0 - -1.0 think \"Sin\"\n  if (period) {\n    if (t>=0.0)\n      return 2.0*(t%period/period)-1.0;\n    else\n      return 2.0*(t%period/period)+1.0;\n  } else\n    return 0.0;\n}\n\npublic F64 Caw(F64 t,F64 period)\n{//Cawtooth. 1.0 - 0.0 think \"(Cos+1)/2\"\n  if (period) {\n    if (t>=0.0)\n      return 1.0-t%period/period;\n    else\n      return -(t%period)/period;\n  } else\n    return 1.0;\n}\n\npublic F64 FullCaw(F64 t,F64 period)\n{//Plus&Minus Cawtooth. 1.0 - -1.0 think \"Cos\"\n  if (period) {\n    if (t>=0.0)\n      return -2.0*(t%period/period)+1.0;\n    else\n      return -2.0*(t%period/period)-1.0;\n  } else\n    return 1.0;\n}\n\npublic F64 Tri(F64 t,F64 period)\n{//Triangle waveform. 0.0 - 1.0 - 0.0\n  if (period) {\n    t=2.0*(Abs(t)%period)/period;\n    if (t<=1.0)\n      return t;\n    else\n      return 2.0-t;\n  } else\n    return 0.0;\n}\n\npublic F64 FullTri(F64 t,F64 period)\n{//Plus&Minus Triangle waveform. 0.0 - 1.0 - 0.0 - -1.0 -0.0\n  if (period) {\n    t=4.0*(t%period)/period;\n    if (t<=-1.0) {\n      if (t<=-3.0)\n\treturn t+4.0;\n      else\n\treturn -2.0-t;\n    } else {\n      if (t<=1.0)\n\treturn t;\n      else if (t<=3.0)\n\treturn 2.0-t;\n      else\n\treturn t-4.0;\n    }\n  } else\n    return 0.0;\n}\n\n#help_index \"Snd/Math\"\n\npublic I8 Note2Ona(I64 note,I64 octave=4)\n{//Note to ona. Mid C is ona=51, note=3 and octave=4.\n  if (note<3)\n    return (octave+1)*12+note;\n  else\n    return octave*12+note;\n}\n\npublic I8 Ona2Note(I8 ona)\n{//Ona to note in octave. Mid C is ona=51, note=3 and octave=4.\n  return ona%12;\n}\n\npublic I8 Ona2Octave(I8 ona)\n{//Ona to octave. Mid C is ona=51, note=3 and octave=4.\n  I64 note=ona%12,octave=ona/12;\n  if (note<3)\n    return octave-1;\n  else\n    return octave;\n}\n\nF64 SinPhaseCont(F64 last_y,F64 last_dydt,\n\t\t    F64 current_amp,F64 phase_offset)\n{//Next sample of sin waveform.\n  F64 phase;\n  phase=last_y/current_amp;\n  if (phase>1.0) phase=1.0;\n  if (phase<-1.0) phase=-1.0;\n  if (last_dydt<0)\n    phase=π-ASin(phase);\n  else\n    phase=ASin(phase);\n  return phase-phase_offset;\n}\n\npublic CSndWaveCtrl *SndWaveCtrlNew(I64 sample_rate=8000,I64 sample_bits=24,\n  I64 channels=2,CTask *mem_task=NULL)\n{//MAlloc ctrl struct for generating waveforms.\n  CSndWaveCtrl *swc=CAlloc(sizeof(CSndWaveCtrl),mem_task);\n  swc->freq_multiplier=1.0;\n  swc->amp_multiplier=1.0;\n  swc->sample_rate=sample_rate;\n  swc->sample_bits=sample_bits;\n  swc->channels=channels;\n  swc->last_dydt=1.0;\n  return swc;\n}\n\npublic U0 SndWaveCtrlDel(CSndWaveCtrl *swc)\n{//Free waveform ctrl.\n  Free(swc);\n}\n\n#define WF_NULL\t\t\t0\n#define WF_SQUARE\t\t1\n#define WF_SINE\t\t\t2\n#define WF_TRI\t\t\t3\n#define WF_SAWTOOTH\t\t4\n#define WF_NOISE\t\t5\n#define WF_WAVEFORMS_NUM\t6\n\npublic U0 SndWaveAddBuf(CSndWaveCtrl *swc,U8 *buf,I64 num_samples,\n  F64 _freq,I64 _waveform=WF_SQUARE,F64 _amp=1.0,F64 _left=1.0, F64 _right=1.0)\n{//Add waveform to buffer.\n//num_samples is multiplied by channels to get buf_len.\n  //left,right range from 0.0-1.0\n  //Supports 16,24 and 32 bits\n  I64 reg i,reg j,reg k;\n  F64 a,f,amp,reg phase;\n  if (!swc) return;\n  _freq*=swc->freq_multiplier;\n  _amp*=swc->amp_multiplier;\n  if (!_freq||!_amp) {\n    swc->last_y=swc->phase=0;\n    swc->last_dydt=1.0;\n  } else {\n    phase=swc->phase;\n    i=0;\n    amp=Min(I32_MAX,I32_MAX*_amp);\n    f=2*π/swc->sample_rate*_freq;\n    switch (_waveform) {\n      case WF_NOISE:\n\ta=2.0/π*amp;\n\tbreak;\n      case WF_SAWTOOTH:\n\ta=amp/π;\n\tbreak;\n      case WF_SINE:\n\tphase=SinPhaseCont(swc->last_y,swc->last_dydt,amp,0.0);\n\tbreak;\n    }\n    while (phase<0)\n      phase+=2*π;\n    while (phase>=2*π)\n      phase-=2*π;\n    num_samples*=swc->channels;\n    while (i<num_samples) {\n      switch (_waveform) {\n\tcase WF_SQUARE:\n\t  if (phase>=π)\n\t    j=-amp;\n\t  else\n\t    j=amp;\n\t  break;\n\tcase WF_SINE:\n\t  j=amp*Sin(phase);\n\t  break;\n\tcase WF_TRI:\n\t  if (phase>=π) {\n\t    swc->last_y=swc->next_y;\n\t    swc->next_y=-amp*Sign(swc->last_y)+.00001;\n\t    phase-=π;\n\t  }\n\t  j=(swc->last_y*(π-phase)+swc->next_y*phase)/π;\n\t  break;\n\tcase WF_SAWTOOTH:\n\t  j=a*(phase-π);\n\t  break;\n\tcase WF_NOISE:\n\t  if (phase<π) {\n\t    if (phase<f) {\n\t      swc->last_y=swc->next_y;\n\t      swc->next_y=a*RandI16/U16_MAX;\n\t    }\n\t    j=swc->last_y*(π-phase)+swc->next_y*phase;\n\t  } else {\n\t    if (phase-π<f) {\n\t      swc->last_y=swc->next_y;\n\t      swc->next_y=a*RandI16/U16_MAX;\n\t    }\n\t    j=swc->last_y*(2.0*π-phase)+swc->next_y*(phase-π);\n\t  }\n\t  break;\n      }\n//left channel\n      k=j*_left;\n      if (swc->sample_bits==16) {\n\tk>>=16;\n\tbuf(I16 *)[i++]+=k;\n      } else {\n\tif (swc->sample_bits==24)\n\t  k&=0xFFFFFF00;\n\tbuf(I32 *)[i++]+=k;\n      }\n//right channel\n      if (swc->channels==2) {\n\tk=j*_right;\n\tif (swc->sample_bits==16) {\n\t  k>>=16;\n\t  buf(I16 *)[i++]+=k;\n\t} else {\n\t  if (swc->sample_bits==24)\n\t    k&=0xFFFFFF00;\n\t  buf(I32 *)[i++]+=k;\n\t}\n      }\n      phase+=f;\n      while (phase>=2*π)\n\tphase-=2*π;\n    }\n    if (_waveform==WF_SINE) {\n      swc->last_y=amp*Sin(phase);\n      swc->last_dydt=Cos(phase);\n    }\n    swc->phase=phase;\n  }\n}\n";
export const SND_MUSIC_SRC="#help_index \"Snd/Music\"\n\npublic class CMusicGlbls\n{\n  U8\t*cur_song;\n  CTask\t*cur_song_task;\n  I64\toctave;\n  F64\tnote_len;\n  U8\tnote_map[7];\n  Bool\tmute;\n  I64\tmeter_top,meter_bottom;\n  F64\ttempo,stacatto_factor;\n\n  //If you wish to sync with a\n  //note in a Play() string.  0 is the start\n  I64\tplay_note_num;\n\n  F64\ttM_correction,last_Beat,last_tM;\n} music={NULL,NULL,4,1.0,{0,2,3,5,7,8,10},FALSE,4,4,2.5,0.9,0,0,0,0};\n\n#help_index \"Snd/Music;Time/Seconds\"\npublic F64 tM()\n";
export const QSORT_SRC="U0 QSortI64(I64 *base,I64 num, I64 (*fp_compare)(I64 e1,I64 e2))\n{/*Quick Sort for width==8.\nfp_compare() passes by value instead of ref.\n\nFor ascending strings: return StrCmp(e1,e2);\nFor ascending ints   : return e1-e2;\n\nMaybe, look at $LK,\"::/Demo/MultiCore/MPRadix.HC\"$.\n*/\n  I64 i,*left,*right,pivot;\n  if (num>1) {\n    left =base;\n    right=base+num-1;\n    pivot=base[num/2];\n    do {\n      while ((*fp_compare)(*left,pivot)<0)\n\tleft++;\n      while ((*fp_compare)(*right,pivot)>0)\n\tright--;\n      if (left<=right)\n\tSwapI64(left++,right--);\n    } while (left<=right);\n    i=right+1-base;\n    if (1<i<num)\n      QSortI64(base,i,fp_compare);\n    i=base+num-left;\n    if (1<i<num)\n      QSortI64(left,i,fp_compare);\n  }\n}\n\nU0 QSort2a(U8 **base,I64 num,I64 (*fp_compare)(U8 **_e1,U8 **_e2))\n{//Not public.For case of width==size(U8 *)==8.\n//fp_compare() passes by ref.\n  I64 i;\n  U8 **left,**right,*pivot;\n  left =base;\n  right=base+num-1;\n  pivot=base[num/2];\n  do {\n    while ((*fp_compare)(left,&pivot)<0)\n      left++;\n    while ((*fp_compare)(right,&pivot)>0)\n      right--;\n    if (left<=right)\n      SwapI64(left++,right--);\n  } while (left<=right);\n  i=right+1-base;\n  if (1<i<num)\n    QSort2a(base,i,fp_compare);\n  i=base+num-left;\n  if (1<i<num)\n    QSort2a(left,i,fp_compare);\n}\nU0 QSort2b(U8 *base,I64 num, I64 width,\n\tI64 (*fp_compare)(U8 *e1,U8 *e2),U8 *tmp)\n{//Not public\n  I64 i;\n  U8 *left,*right,*pivot=tmp+width;\n  left =base;\n  right=base+(num-1)*width;\n  MemCpy(pivot,base+num/2*width,width);\n  do {\n    while ((*fp_compare)(left,pivot)<0)\n      left+=width;\n    while ((*fp_compare)(right,pivot)>0)\n      right-=width;\n    if (left<=right) {\n      if (left!=right) {\n\tMemCpy(tmp,right,width);\n\tMemCpy(right,left,width);\n\tMemCpy(left,tmp,width);\n      }\n      left+=width;\n      right-=width;\n    }\n  } while (left<=right);\n  i=1+(right-base)/width;\n  if (1<i<num)\n    QSort2b(base,i,width,fp_compare,tmp);\n  i=num+(base-left)/width;\n  if (1<i<num)\n    QSort2b(left,i,width,fp_compare,tmp);\n}\nU0 QSort(U8 *base,I64 num, I64 width, I64 (*fp_compare)(U8 *e1,U8 *e2))\n{/*Quick Sort: fp_compare() passes by ref.\n\nFor ascending strings: return StrCmp(*e1,*e2);\nFor ascending ints   : return *e1-*e2;\nDon't return e1-e2 if numbers can overflow, return -1,0 or 1.\n\nMaybe, look at $LK,\"::/Demo/MultiCore/MPRadix.HC\"$.\n*/\n  U8 *tmp;\n  if (width && num>1) {\n    if (width==sizeof(U8 *))\t//assign instead of MemCpy for width 8\n      QSort2a(base,num,fp_compare);\n    else {\n      tmp=MAlloc(width*2);\n      QSort2b(base,num,width,fp_compare,tmp);\n      Free(tmp);\n    }\n  }\n}\n";
export const SND_EFFECTS_SRC="#help_index \"Snd\"\n\n#define SE_NOISE\t0\n#define SE_SWEEP\t1\n\nclass CSoundEffectFrame\n{\n  I32\ttype;\n  I8\tona1,ona2;\n  F64\tduration;\n};\n\nU0 SoundEffectEndTaskCB()\n{\n  Free(FramePtr(\"CSoundEffectFrame\"));\n  music.mute--;\n  SndTaskEndCB;\n}\n\nU0 SoundEffectTask(CSoundEffectFrame *ns)\n{\n  I64 i,ona;\n  F64 t0=tS,t,timeout=t0+ns->duration;\n  FramePtrAdd(\"CSoundEffectFrame\",ns);\n  Fs->task_end_cb=&SoundEffectEndTaskCB;\n  switch (ns->type) {\n    case SE_NOISE:\n      i=MaxI64(ns->ona2-ns->ona1,1);\n      while (tS<timeout) {\n\tona=RandU16%i+ns->ona1;\n\tSnd(ona);\n\tt=Clamp(3000.0/Ona2Freq(ona),1.0,50.0);\n\tif (t+tS>timeout)\n\t  t=timeout-tS;\n\tSleep(t);\n      }\n      break;\n    case SE_SWEEP:\n      while (tS<timeout) {\n\tt=(tS-t0)/ns->duration;\n\tona=(1.0-t)*ns->ona1+t*ns->ona2;\n\tSnd(ona);\n\tt=Clamp(3000.0/Ona2Freq(ona),1.0,50.0);\n\tif (t+tS>timeout)\n\t  t=timeout-tS;\n\tSleep(t);\n      }\n      break;\n  }\n}\n\npublic CTask *Noise(I64 mS,F64 min_ona,F64 max_ona)\n{//Make white noise for given number of mS.\n  CSoundEffectFrame *ns;\n  if (mS>0) {\n    ns=MAlloc(sizeof(CSoundEffectFrame));\n    ns->type=SE_NOISE;\n    ns->duration=mS/1000.0;\n    ns->ona1=min_ona;\n    ns->ona2=max_ona;\n    music.mute++;\n    return Spawn(&SoundEffectTask,ns,\"Noise\",,Fs);\n  } else\n    return NULL;\n}\n\npublic CTask *Sweep(I64 mS,F64 ona1,F64 ona2)\n{//Sweep through freq range in given number of mS.\n  CSoundEffectFrame *ns;\n  if (mS>0) {\n    ns=MAlloc(sizeof(CSoundEffectFrame));\n    ns->type=SE_SWEEP;\n    ns->duration=mS/1000.0;\n    ns->ona1=ona1;\n    ns->ona2=ona2;\n    music.mute++;\n    return Spawn(&SoundEffectTask,ns,\"Noise\",,Fs);\n  } else\n    return NULL;\n}\n";
